public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt(); //参加者
		int K = sc.nextInt(); //ポイント
		int Q = sc.nextInt(); //クイズの回数
		int A[] =  new int[Q]; //正解者
