            int answer = std.nextInt() - 1;
            points[answer] += 1;
        }

        for (int i = 0; i < n; i++) {
            int minusPoint = q - points[i];
            if(k - minusPoint > 0) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }
    }
}

